// A Tov function called from JavaScript, the way a framework calls a handler: with a `ctx` whose
// `params` is a lazy getter that throws (validation, as velox's) and whose `boom()` throws.
// Whatever the callback throws is caught here, as a framework's error handler catches it.

let lastThrown;

function makeCtx() {
  return {
    ok: 7,
    get params() {
      lastThrown = new Error("boom-getter");
      throw lastThrown;
    },
    boom() {
      lastThrown = new Error("bang-method");
      throw lastThrown;
    },
  };
}

function describe(e) {
  const same = e === lastThrown ? " (the thrown object)" : "";
  const name = e instanceof Error ? `${e.name}: ${e.message}` : String(e);
  return `caught ${name}${same}`;
}

// cb(ctx), synchronously
export function run(cb) {
  lastThrown = undefined;
  try {
    return `returned ${cb(makeCtx())}`;
  } catch (e) {
    return describe(e);
  }
}

// cb(ctx), whose result may be a promise
export async function runAsync(cb) {
  lastThrown = undefined;
  try {
    return `returned ${await cb(makeCtx())}`;
  } catch (e) {
    return describe(e);
  }
}

// cb called from a promise reaction (a framework's microtask)
export function runLater(cb) {
  lastThrown = undefined;
  return Promise.resolve().then(() => cb(makeCtx())).then((v) => `returned ${v}`, describe);
}

// cb called with a JS function it can call back into: JS -> Tov -> JS -> Tov
export function runNested(outer, inner) {
  lastThrown = undefined;
  try {
    return `returned ${outer(() => {
      try {
        return `inner returned ${inner(makeCtx())}`;
      } catch (e) {
        return `inner ${describe(e)}`;
      }
    })}`;
  } catch (e) {
    return `outer ${describe(e)}`;
  }
}

// Bun.serve with a handler, answering errors with a 500 as velox's handleError does; then the
// requests, in order: "status body" for each
export async function serve(handler, paths) {
  const server = Bun.serve({
    port: 0,
    fetch(req) {
      try {
        return new Response(String(handler(makeCtx(), new URL(req.url).pathname)));
      } catch (e) {
        return new Response(e instanceof Error ? e.message : String(e), { status: 500 });
      }
    },
  });
  const out = [];
  for (const p of paths) {
    const res = await fetch(`http://localhost:${server.port}${p}`);
    out.push(`${p} ${res.status} ${await res.text()}`);
  }
  await server.stop();
  return out.join("\n");
}
